    /** provider 별 mode 조회. 알 수 없으면 "mock". */
    public String modeOf(String provider) {
        return switch (provider == null ? "" : provider) {
            case "google" -> google.getMode();
            case "kakao" -> kakao.getMode();
            case "naver" -> naver.getMode();
            default -> "mock";
