 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_HOST = System.getProperty("test.redis.host", "localhost");
    private static final int REDIS_PORT = Integer.getInteger("test.redis.port", 6379);

    private static final String REDIS_TOKEN_PREFIX = "auth:token:";
    private static final long TOKEN_TTL_SECONDS = 3600L;
    private static final String DISPLAY_NAME = "익명";
    private static final String UUID_PATTERN =
            "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$";

    // 병렬 안전: 각 SQL 실행/Redis 조회마다 독립 Connection을 사용
    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    // 메서드별 고유 ID 생성 (결정적 -- 메서드명 기반)
    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthLoginBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static void teardownByIdentity(String socialProvider, String externalId) {
        executeSqlTemplate("sql/auth-login-teardown.sql", Map.of(
                "SOCIAL_PROVIDER", socialProvider,
                "EXTERNAL_ID", externalId));
    }

    /** DB에서 (social_provider, external_id)로 user_account 행을 직접 조회. */
    private static ResultRow findUserAccount(String socialProvider, String externalId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT id FROM user_account WHERE social_provider = ? AND external_id = ?")) {
            ps.setString(1, socialProvider);
            ps.setString(2, externalId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next(), "expected a user_account row for " + socialProvider + "/" + externalId);
                String id = rs.getString("id");
                assertTrue(!rs.next(), "expected exactly one user_account row for " + socialProvider + "/" + externalId);
                return new ResultRow(id);
            }
        }
    }

    private static int countUserAccounts(String socialProvider, String externalId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT COUNT(*) AS cnt FROM user_account WHERE social_provider = ? AND external_id = ?")) {
            ps.setString(1, socialProvider);
            ps.setString(2, externalId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next());
                return rs.getInt("cnt");
            }
        }
    }

    private record ResultRow(String id) {}

    /** Redis 에서 auth:token:<token> -> userId 매핑과 TTL을 raw Lettuce 클라이언트로 직접 검증. */
    private static void assertRedisTokenMapsTo(String token, String expectedUserId) {
        RedisClient client = RedisClient.create("redis://" + REDIS_HOST + ":" + REDIS_PORT + "/0");
        try (StatefulRedisConnection<String, String> conn = client.connect()) {
            RedisCommands<String, String> commands = conn.sync();
            String key = REDIS_TOKEN_PREFIX + token;
            String actualUserId = commands.get(key);
            assertEquals(expectedUserId, actualUserId, "Redis token->userId mapping mismatch for key " + key);
            Long ttl = commands.ttl(key);
            assertTrue(ttl != null && ttl > 0 && ttl <= TOKEN_TTL_SECONDS,
                    "Redis TTL for " + key + " expected in (0," + TOKEN_TTL_SECONDS + "] but was " + ttl);
