            client.shutdown();
        }
    }

    // ------------------------------------------------------------------
    // NTC (Happy Path) -- 4 cases
    // ------------------------------------------------------------------

    @Test
    void NTC_login_newUser_kakao_createsAccountAndIssuesToken(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "kakao";
        String externalId = provider + ":" + id;

        teardownByIdentity(provider, externalId);
        try {
            String accessToken =
                given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(Map.of("provider", provider, "providerToken", "valid-" + provider + "-" + id))
                .when()
                    .post("/api/v1/auth/login")
                .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo(DISPLAY_NAME))
                    .extract().path("accessToken");

            ResultRow row = findUserAccount(provider, externalId);
            assertRedisTokenMapsTo(accessToken, row.id());
        } finally {
            teardownByIdentity(provider, externalId);
        }
    }

    @Test
    void NTC_login_existingUser_reusesAccountNoNewRowCreated(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "google";
        String externalId = provider + ":" + id;
        String presetUserId = "existing-" + id;

        Map<String, String> identityParams = Map.of("SOCIAL_PROVIDER", provider, "EXTERNAL_ID", externalId);
        Map<String, String> setupParams = new HashMap<>(identityParams);
        setupParams.put("ID", presetUserId);
        setupParams.put("CREATED_AT", "2020-01-01 00:00:00");

        executeSqlTemplate("sql/auth-login-setup.sql", setupParams);
        try {
            String accessToken =
                given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(Map.of("provider", provider, "providerToken", "valid-" + provider + "-" + id))
                .when()
                    .post("/api/v1/auth/login")
                .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo(DISPLAY_NAME))
                    .extract().path("accessToken");

            assertEquals(1, countUserAccounts(provider, externalId), "login must not create a duplicate row for an existing identity");
            ResultRow row = findUserAccount(provider, externalId);
            assertEquals(presetUserId, row.id(), "existing account id must be reused, not replaced with a new UUID");
            assertRedisTokenMapsTo(accessToken, presetUserId);
        } finally {
            teardownByIdentity(provider, externalId);
        }
    }

    @Test
    void NTC_login_tossProvider_alwaysUsesMockRegardlessOfConfig(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "toss";
        String externalId = provider + ":" + id;

        teardownByIdentity(provider, externalId);
        try {
            String accessToken =
                given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(Map.of("provider", provider, "providerToken", "valid-" + provider + "-" + id))
                .when()
                    .post("/api/v1/auth/login")
                .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo(DISPLAY_NAME))
                    .extract().path("accessToken");

            ResultRow row = findUserAccount(provider, externalId);
            assertRedisTokenMapsTo(accessToken, row.id());
        } finally {
            teardownByIdentity(provider, externalId);
        }
    }

    @Test
    void NTC_login_sameIdentityTwice_secondCallReusesAccountWithNewToken(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "naver";
        String externalId = provider + ":" + id;
        Map<String, Object> body = Map.of("provider", provider, "providerToken", "valid-" + provider + "-" + id);

        teardownByIdentity(provider, externalId);
        try {
            String accessToken1 =
                given().baseUri(BASE_URL).contentType(ContentType.JSON).body(body)
                .when().post("/api/v1/auth/login")
                .then().statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .extract().path("accessToken");

            ResultRow rowAfterFirst = findUserAccount(provider, externalId);

            String accessToken2 =
                given().baseUri(BASE_URL).contentType(ContentType.JSON).body(body)
                .when().post("/api/v1/auth/login")
                .then().statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .extract().path("accessToken");

            assertNotEquals(accessToken1, accessToken2, "each login call must issue a fresh token");
            assertEquals(1, countUserAccounts(provider, externalId), "second login for the same identity must not create a second row");
            ResultRow rowAfterSecond = findUserAccount(provider, externalId);
            assertEquals(rowAfterFirst.id(), rowAfterSecond.id(), "second login for the same identity must reuse the same user id");

            assertRedisTokenMapsTo(accessToken1, rowAfterFirst.id());
            assertRedisTokenMapsTo(accessToken2, rowAfterSecond.id());
        } finally {
            teardownByIdentity(provider, externalId);
        }
    }

    // ------------------------------------------------------------------
    // ATC (Business Exception -- 401 via InvalidTokenException) -- 3 cases
    // No DB row is ever created for these: CompositeSocialVerifier/MockSocialVerifier
    // throw InvalidTokenException before AuthService.login reaches repository.save.
    // ------------------------------------------------------------------

    @Test
    void ATC_login_unsupportedProvider_returns401InvalidToken() {
        given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(Map.of("provider", "facebook", "providerToken", "whatever"))
        .when()
            .post("/api/v1/auth/login")
        .then().log().all()
            .statusCode(401)
            .contentType(containsString("application/problem+json"))
            .body("title", equalTo("Invalid token"))
            .body("detail", equalTo("unsupported provider: facebook"));
    }

    @Test
    void ATC_login_malformedToken_returns401InvalidToken() {
        given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(Map.of("provider", "kakao", "providerToken", "not-the-right-format"))
        .when()
            .post("/api/v1/auth/login")
        .then().log().all()
            .statusCode(401)
            .contentType(containsString("application/problem+json"))
            .body("title", equalTo("Invalid token"))
            .body("detail", equalTo("malformed token for provider: kakao"));
    }

    @Test
    void ATC_login_emptySeed_returns401InvalidToken() {
        given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(Map.of("provider", "naver", "providerToken", "valid-naver-"))
        .when()
            .post("/api/v1/auth/login")
        .then().log().all()
            .statusCode(401)
            .contentType(containsString("application/problem+json"))
            .body("title", equalTo("Invalid token"))
            .body("detail", equalTo("empty seed"));
    }

    // ------------------------------------------------------------------
    // VTC (Bean Validation -- 400) -- 6 cases: NULL/EMPTY/WHITE_SPACE x {provider, providerToken}
    //
    // RED params (manually identified -- generate-test-plan/generate-vtc-from-red-params
    // returned empty output for this method; see project memory): `provider` (switch/branch
    // in CompositeSocialVerifier + SUPPORTED-set check in MockSocialVerifier) and
    // `providerToken` (prefix/equality check in MockSocialVerifier). Neither is used in a
    // real SQL WHERE clause (in-memory Set.contains/startsWith only), so SPECIAL_CHAR does
    // not qualify (rule requires DB_WHERE). Neither field has an @Size constraint, so
    // LENGTH_EXCEEDED/LENGTH_SHRUNK do not apply. Neither is date/number-parsed, so
    // INVALID_FORMAT does not apply. NULL/EMPTY apply unconditionally per the VTC standard
    // rule table; WHITE_SPACE applies because both params are used in an equality/prefix
    // check.
    //
    // Ground truth for the response shape (AuthControllerWebTest.login_blankProvider_...):
    // spring.mvc.problemdetails.enabled=true means Spring's framework-default ProblemDetail
    // handler shadows GlobalExceptionHandler.handleValidation for MethodArgumentNotValidException,
    // so only statusCode(400) + content-type are asserted here, not exact title/detail text.
    // ------------------------------------------------------------------

    private static Map<String, Object> loginBody(Object provider, Object providerToken) {
        Map<String, Object> body = new HashMap<>();
        body.put("provider", provider);
        body.put("providerToken", providerToken);
        return body;
    }

    private static void assertBadRequest(Map<String, Object> body) {
        given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(body)
        .when()
            .post("/api/v1/auth/login")
        .then().log().all()
            .statusCode(400)
            .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_provider_NULL(TestInfo info) {
        String id = testId(info);
        assertBadRequest(loginBody(null, "valid-kakao-" + id));
    }

    @Test
    void VTC_provider_EMPTY(TestInfo info) {
        String id = testId(info);
        assertBadRequest(loginBody("", "valid-kakao-" + id));
    }

    @Test
    void VTC_provider_WHITE_SPACE(TestInfo info) {
        String id = testId(info);
        assertBadRequest(loginBody(" \t\n", "valid-kakao-" + id));
    }

    @Test
    void VTC_providerToken_NULL() {
        assertBadRequest(loginBody("kakao", null));
    }

    @Test
    void VTC_providerToken_EMPTY() {
        assertBadRequest(loginBody("kakao", ""));
    }

    @Test
    void VTC_providerToken_WHITE_SPACE() {
        assertBadRequest(loginBody("kakao", " \t\n"));
    }
}

