    @Test
    void NTC_login_sameIdentityTwice_secondCallReusesAccountWithNewToken(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "naver";
        String externalId = provider + ":" + id;
        Map<String, Object> body = Map.of("provider", provider, "providerToken", "valid-" + provider + "-" + id);

        teardownByIdentity(provider, externalId);
        try {
            String accessToken1 =
                given().baseUri(BASE_URL).contentType(ContentType.JSON).body(body)
                .when().post("/api/v1/auth/login")
                .then().statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .extract().path("accessToken");

            ResultRow rowAfterFirst = findUserAccount(provider, externalId);

            String accessToken2 =
                given().baseUri(BASE_URL).contentType(ContentType.JSON).body(body)
                .when().post("/api/v1/auth/login")
                .then().statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .extract().path("accessToken");

            assertNotEquals(accessToken1, accessToken2, "each login call must issue a fresh token");
            assertEquals(1, countUserAccounts(provider, externalId), "second login for the same identity must not create a second row");
            ResultRow rowAfterSecond = findUserAccount(provider, externalId);
            assertEquals(rowAfterFirst.id(), rowAfterSecond.id(), "second login for the same identity must reuse the same user id");

            assertRedisTokenMapsTo(accessToken1, rowAfterFirst.id());
            assertRedisTokenMapsTo(accessToken2, rowAfterSecond.id());
        } finally {
            teardownByIdentity(provider, externalId);
        }
    }

