    // ------------------------------------------------------------------
    // VTC (Bean Validation -- 400) -- 6 cases: NULL/EMPTY/WHITE_SPACE x {provider, providerToken}
    //
    // RED params (manually identified -- generate-test-plan/generate-vtc-from-red-params
    // returned empty output for this method; see project memory): `provider` (switch/branch
    // in CompositeSocialVerifier + SUPPORTED-set check in MockSocialVerifier) and
    // `providerToken` (prefix/equality check in MockSocialVerifier). Neither is used in a
    // real SQL WHERE clause (in-memory Set.contains/startsWith only), so SPECIAL_CHAR does
    // not qualify (rule requires DB_WHERE). Neither field has an @Size constraint, so
    // LENGTH_EXCEEDED/LENGTH_SHRUNK do not apply. Neither is date/number-parsed, so
    // INVALID_FORMAT does not apply. NULL/EMPTY apply unconditionally per the VTC standard
    // rule table; WHITE_SPACE applies because both params are used in an equality/prefix
    // check.
    //
    // Ground truth for the response shape (AuthControllerWebTest.login_blankProvider_...):
    // spring.mvc.problemdetails.enabled=true means Spring's framework-default ProblemDetail
    // handler shadows GlobalExceptionHandler.handleValidation for MethodArgumentNotValidException,
    // so only statusCode(400) + content-type are asserted here, not exact title/detail text.
    // ------------------------------------------------------------------

    private static Map<String, Object> loginBody(Object provider, Object providerToken) {
        Map<String, Object> body = new HashMap<>();
        body.put("provider", provider);
        body.put("providerToken", providerToken);
        return body;
    }

    private static void assertBadRequest(Map<String, Object> body) {
        given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(body)
        .when()
            .post("/api/v1/auth/login")
        .then().log().all()
            .statusCode(400)
            .contentType(containsString("application/problem+json"));
    }

